INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','8','ar','شحن Robux عبر اسم المستخدم — فوري','شحن Robux أصلي عبر اسم المستخدم. يقوم البائع بإتمام التسليم يدويًا، عادةً خلال 15 دقيقة.\n\nالمنطقة: عالمي. المنصة: PC / الجوال.\n\nطريقة الاسترداد: اتبع التعليمات المرسلة مع طلبك. تواصل مع البائع من صفحة طلبك إذا حدث أي خطأ.','2026-10-16 05:47:20');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','8','es','Recarga de Robux por nombre de usuario — Instantáneo','Recarga auténtica de Robux por nombre de usuario. El vendedor completa la entrega manualmente, normalmente en 15 minutos.\n\nRegión: Global. Plataforma: PC / Móvil.\n\nCómo canjear: sigue las instrucciones enviadas con tu pedido. Contacta al vendedor desde la página de tu pedido si algo sale mal.','2026-10-16 05:47:20');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','8','fr','Recharge de Robux par nom d’utilisateur — Instantané','Recharge de Robux authentique par nom d’utilisateur. Le vendeur effectue la livraison manuellement, généralement sous 15 minutes.\n\nRégion : Mondial. Plateforme : PC / Mobile.\n\nComment utiliser : suivez les instructions envoyées avec votre commande. Contactez le vendeur depuis la page de votre commande si quelque chose ne va pas.','2026-10-16 05:47:20');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','8','id','Isi ulang Robux berdasarkan nama pengguna — Instan','Isi ulang Robux asli berdasarkan nama pengguna. Penjual menyelesaikan pengiriman secara manual, biasanya dalam 15 menit.\n\nWilayah: Global. Platform: PC / Mobile.\n\nCara menebus: ikuti instruksi yang dikirim bersama pesanan Anda. Hubungi penjual dari halaman pesanan Anda jika ada yang salah.','2026-10-16 05:47:20');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','8','ko','사용자 이름으로 Robux 충전 — 즉시','사용자 이름으로 정품 Robux 충전. 판매자가 수동으로 배송하며, 보통 15분 이내에 완료됩니다.\n\n지역: 전 세계. 플랫폼: PC / 모바일.\n\n사용 방법: 주문과 함께 전송된 안내를 따르세요. 문제가 발생하면 주문 페이지에서 판매자에게 문의하세요.','2026-10-16 05:47:20');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','8','ru','Пополнение Robux по имени пользователя — Мгновенно','Оригинальное пополнение Robux по имени пользователя. Продавец выполняет доставку вручную, обычно в течение 15 минут.\n\nРегион: Глобально. Платформа: PC / Мобильное устройство.\n\nКак активировать: следуйте инструкциям, отправленным вместе с вашим заказом. Свяжитесь с продавцом со страницы вашего заказа, если что-то пойдёт не так.','2026-10-16 05:47:20');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','8','zh','通过用户名充值 Robux — 即时','通过用户名进行正版 Robux 充值。卖家会手动完成交付，通常在 15 分钟内。\n\n地区：全球。平台：PC / 移动设备。\n\n如何兑换：请按照随订单发送的说明操作。如果出现任何问题，请从订单页面联系卖家。','2026-10-16 05:47:20');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','9','ar','تسليم Robux سريع إلى حسابك','تسليم Robux سريع وأصلي إلى حسابك. يُكمل البائع التسليم يدويًا، عادةً خلال 15 دقيقة.\n\nالمنطقة: عالمي. المنصة: PC / Mobile.\n\nكيفية الاسترداد: اتبع التعليمات المرسلة مع طلبك. اتصل بالبائع من صفحة طلبك إذا حدث أي خطأ.','2026-10-16 05:47:20');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','9','es','Entrega rápida de Robux a tu cuenta','Entrega rápida y auténtica de Robux a tu cuenta. El vendedor completa la entrega manualmente, normalmente en 15 minutos.\n\nRegión: Global. Plataforma: PC / Mobile.\n\nCómo canjear: sigue las instrucciones enviadas con tu pedido. Contacta al vendedor desde la página de tu pedido si algo sale mal.','2026-10-16 05:47:20');
